// Fast bidirectional lookup maps
const PRESET_MAP = new Map();
const RUMOUR_CORRECTION_MAP = new Map();

NEWS_PRESETS_LIBRARY.forEach(p => {
  PRESET_MAP.set(p.presetId.toUpperCase(), p);
  PRESET_MAP.set(p.id.toUpperCase(), p);
  if (p.legacyId) PRESET_MAP.set(p.legacyId.toUpperCase(), p);
  PRESET_MAP.set(String(p.sequence), p);
  PRESET_MAP.set(`NEWS${p.sequence}`, p);

  if (p.correctionRules && p.correctionRules.resolutionPresetId) {
    RUMOUR_CORRECTION_MAP.set(p.id, p.correctionRules.resolutionPresetId);
    RUMOUR_CORRECTION_MAP.set(p.presetId, p.correctionRules.resolutionPresetId);
  }
});

export function getPresetById(id) {
  if (!id) return null;
  const key = String(id).trim().toUpperCase();
  return PRESET_MAP.get(key) || null;
}

export function getPresetBySequence(seq) {
  return PRESET_MAP.get(String(seq)) || null;
}

export function getPresetsByCategory(category) {
  if (!category || category === 'All') return [...NEWS_PRESETS_LIBRARY];
  return NEWS_PRESETS_LIBRARY.filter(p => p.category === category);
}

export function getPresetsByScope(scope) {
  if (!scope || scope === 'All') return [...NEWS_PRESETS_LIBRARY];
  const targetScope = scope.toUpperCase();
  return NEWS_PRESETS_LIBRARY.filter(p => (p.scope || '').toUpperCase() === targetScope);
}

export function getPresetsBySearch(query) {
  if (!query || !query.trim()) return [...NEWS_PRESETS_LIBRARY];
  const q = query.toLowerCase().trim();
  return NEWS_PRESETS_LIBRARY.filter(p => {
    return (
      (p.headline && p.headline.toLowerCase().includes(q)) ||
      (p.shortHeadline && p.shortHeadline.toLowerCase().includes(q)) ||
      (p.description && p.description.toLowerCase().includes(q)) ||
      (p.category && p.category.toLowerCase().includes(q)) ||
      (p.subcategory && p.subcategory.toLowerCase().includes(q)) ||
      (p.country && p.country.toLowerCase().includes(q)) ||
      (p.id && p.id.toLowerCase().includes(q)) ||
      (p.presetId && p.presetId.toLowerCase().includes(q)) ||
      (p.legacyId && p.legacyId.toLowerCase().includes(q)) ||
      (String(p.sequence) === q) ||
      (p.affectedSecurityIds && p.affectedSecurityIds.some(s => s.toLowerCase().includes(q))) ||
      (p.affectedTickers && p.affectedTickers.some(s => s.toLowerCase().includes(q))) ||
      (p.affectedSectors && p.affectedSectors.some(sec => sec.toLowerCase().includes(q)))
    );
  });
}

export function getLinkedCorrection(rumourId) {
  const correctionId = RUMOUR_CORRECTION_MAP.get(rumourId);
  return correctionId ? getPresetById(correctionId) : null;
}

export function validateNewsPreset(preset) {
  const errors = [];
  if (!preset) return { valid: false, errors: ['Preset object required'] };
  if (!preset.presetId) errors.push('presetId is required');
  if (typeof preset.sequence !== 'number') errors.push('sequence number is required');
  if (!preset.headline) errors.push('Headline is required');
  if (!preset.category) errors.push('Category is required');

  return {
    valid: errors.length === 0,
    errors
  };
}

export const NEWS_PRESETS = NEWS_PRESETS_LIBRARY;
export const searchPresets = getPresetsBySearch;
export { PRESET_MAP };

export default NEWS_PRESETS_LIBRARY;
